// This declaration.d.ts is used to declare modules for various asset types
// without this, TypeScript may throw errors when importing these files.

declare module "*.png";
declare module "*.jpg";
declare module "*.jpeg";
declare module "*.svg";
declare module "*.pdf";
declare module "*.gif"
declare module "*.webp";
declare module "*.mp4";
declare module "*.mp3"
declare module "*.wav";

// You can add more declarations as needed for other asset types